CREATE OR REPLACE FUNCTION security.ai_use_allowed_v1(p_use text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_mode text; v_bal numeric; v_floor numeric; g record;
begin
  select t.enforcement into v_mode from pipeline.platform_toolsets t where t.key = 'openrouter';
  if coalesce(v_mode, 'observe') <> 'stop' then return true; end if;
  select o.remaining_usd into v_bal from pipeline.layer3_openrouter_observations o where o.kind = 'credits' order by o.observed_at desc limit 1;
  v_floor := coalesce((security.toolset_setting('openrouter', 'credit_floor_usd'))::text::numeric, 0);
  if v_bal is not null and v_bal < v_floor then return false; end if;
  select * into g from security.ai_spend_today_v1() x where x.use = p_use;
  return not (coalesce(g.guard, 0) > 0 and coalesce(g.spent, 0) >= g.guard);
end $function$

public.svc_coverage_ai_match_record(bigi.def:
CREATE OR REPLACE FUNCTION public.svc_coverage_ai_match_record(p_id bigint, p_url text, p_answer jsonb, p_model text, p_cost numeric, p_error text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'catalogue', 'pipeline', 'security'
AS $function$
declare q pipeline.coverage_ai_match%rowtype; v_state text;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  select * into q from pipeline.coverage_ai_match where id = p_id for update;
  if q.id is null or q.state <> 'leased' then return 'not_leased'; end if;
  if p_error ~ '^HTTP (401|402|403|429)\M' or p_error = 'time budget' then
    update pipeline.coverage_ai_match set state = 'ready', leased_until = null where id = p_id;
    return 'released';
  end if;
  if p_error is not null then
    v_state := 'error';
  elsif p_url is null then
    v_state := 'none';
  elsif not exists (select 1 from jsonb_array_elements(q.candidates) x where x->>'url' = p_url) then
    v_state := 'error'; p_answer := coalesce(p_answer, '{}'::jsonb) || jsonb_build_object('refused', 'chosen address is not one of the candidates');
  else
    v_state := 'chosen';
    insert into pipeline.coverage_course_pages(course_id, provider_id, url, score, runner_up, basis, status, bound_at, next_read_at, read_attempts)
    values (q.course_id, q.provider_id, p_url, null, null, 'ai_match', 'bound', now(), now(), 0)
    on conflict (course_id) do update set url = excluded.url, score = null, runner_up = null, basis = 'ai_match', status = 'bound', bound_at = now(),
           next_read_at = now(), read_attempts = 0, read_status = null, identity_basis = null, leased_until = null
     where (pipeline.coverage_course_pages.status = 'mismatch' or pipeline.coverage_course_pages.basis = 'ai_match')
       and coalesce(pipeline.coverage_course_pages.basis, '') <> 'manual';
  end if;
  update pipeline.coverage_ai_match set state = v_state, chosen_url = case when v_state = 'chosen' then p_url end, answer = coalesce(p_answer, '{}'::jsonb) || case when p_error is not null then jsonb_build_object('error', left(p_error, 300)) else '{}'::jsonb end,
         model = p_model, cost_usd = p_cost, decided_at = now(), leased_until = null
   where id = p_id;
  return v_state;
end $function$

security.fc_budget_left_v1(text).def:
CREATE OR REPLACE FUNCTION security.fc_budget_left_v1(p_purpose text)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_grp text := security.fc_purpose_group_v1(p_purpose); v_used numeric;
begin
  if not coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = 'daily_budget_on'), false) then return 1000000; end if;
  -- CF-247 21 Oct 2026: on-demand spends (manual enrichment plan runs) have their own allowance and do not use up the automatic budget
  if security.fc_billed_today_v1() - security.fc_on_demand_today_v1() >= security.fc_setting_num_v1('daily_budget_total', 15000) then return 0; end if;
  select coalesce(sum(x.units), 0) into v_used from pipeline.coverage_vendor_usage x where x.at >= security.fc_day_start_v1() and security.fc_purpose_group_v1(x.purpose) = v_grp and x.on_demand_run is null;
  return greatest(0, security.fc_setting_num_v1('daily_share_' || v_grp, 0) - v_used);
end $function$

security.layer2_provider_budget_status(u.def:
CREATE OR REPLACE FUNCTION security.layer2_provider_budget_status(p_provider_id uuid, p_planned_units numeric DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'security', 'pipeline'
AS $function$
declare
  v_provider pipeline.layer2_acquisition_providers%rowtype;
  v_limit numeric;
  v_stop numeric:=0;
  v_unit numeric:=1;
  v_used numeric:=0;
  v_remaining numeric;
  v_allowed boolean:=true;
begin
  select * into v_provider from pipeline.layer2_acquisition_providers where id=p_provider_id;
  if not found then raise exception 'Layer 2 provider not found' using errcode='22023'; end if;
  begin v_limit:=nullif(v_provider.billing_config->>'monthly_vendor_units_limit','')::numeric; exception when invalid_text_representation then v_limit:=null; end;
  begin v_stop:=coalesce(nullif(v_provider.billing_config->>'stop_at_vendor_units_remaining','')::numeric,0); exception when invalid_text_representation then v_stop:=0; end;
  begin v_unit:=coalesce(nullif(v_provider.request_template->>'fixed_credit_units','')::numeric,1); exception when invalid_text_representation then v_unit:=1; end;
  if v_limit is null then
    return jsonb_build_object('provider_id',p_provider_id,'provider_key',v_provider.provider_key,'bounded',false,'planned_units',greatest(coalesce(p_planned_units,v_unit),0),'allowed',true);
  end if;
  select count(*)::numeric*v_unit into v_used
  from pipeline.layer2_provider_attempts
  where acquisition_provider_id=p_provider_id
    and started_at>=date_trunc('month',now())
    and started_at<date_trunc('month',now())+interval '1 month'; v_used:=v_used+coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.acquisition_provider_id=p_provider_id and u.at>=date_trunc('month',now()) and u.at<date_trunc('month',now())+interval '1 month'),0);
  v_remaining:=greatest(v_limit-v_used,0);
  -- the vendor's own balance (read every 15 minutes) less what the platform used since, when lower
  -- Decision 253: Firecrawl's own balance is the authority when read in the last 2 hours.
  v_remaining:=coalesce((select greatest(o.remaining_units
      - coalesce((select sum(u.units) from pipeline.coverage_vendor_usage u where u.acquisition_provider_id=p_provider_id and u.at>o.observed_at),0)
      - (select count(*)::numeric*v_unit from pipeline.layer2_provider_attempts a where a.acquisition_provider_id=p_provider_id and a.started_at>o.observed_at),0)
    from pipeline.vendor_credit_observations o where o.provider_id=p_provider_id and o.observed_at>now()-interval '2 hours'
    order by o.observed_at desc limit 1), v_remaining);
  v_allowed:=(v_remaining-greatest(coalesce(p_planned_units,v_unit),0))>=v_stop;
  return jsonb_build_object(
    'provider_id',p_provider_id,'provider_key',v_provider.provider_key,'bounded',true,
    'period_start',date_trunc('month',now()),'period_end',date_trunc('month',now())+interval '1 month',
    'limit_units',v_limit,'used_units',v_used,'remaining_units',v_remaining,
    'planned_units',greatest(coalesce(p_planned_units,v_unit),0),'remaining_after_planned',greatest(v_remaining-greatest(coalesce(p_planned_units,v_unit),0),0),
    'stop_at_remaining_units',v_stop,'allowed',v_allowed,
    'no_silent_paid_fallback',coalesce((v_provider.billing_config->>'no_silent_paid_fallback')::boolean,false)
  );
end
$function$

public.svc_fc_spend(numeric,text,uuid,te.def:
CREATE OR REPLACE FUNCTION public.svc_fc_spend(p_units numeric, p_purpose text, p_provider_id uuid, p_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_grp text := security.fc_purpose_group_v1(p_purpose); v_why text; v_host text := security.fc_spend_host_v1(p_url);
  -- CF-247 21 Oct 2026: a university with a manual enrichment plan run spends from the on-demand allowance
  v_od uuid := case when p_provider_id is null then null else (select r.id from pipeline.enrich_plan_runs r where r.provider_id = p_provider_id and r.mode = 'manual' and r.state = 'running' limit 1) end;
begin
  if current_user <> 'postgres' and coalesce(auth.role(), '') <> 'service_role' then raise exception 'service_role required'; end if;
  -- v2.15.265 (Platform Admin, 13 Oct 2026): never a credit on a directory site (a page on it, or a search limited to it), whatever the purpose
  if v_host is not null and security.third_party_host_v1('https://' || v_host) then
    v_why := 'directory_site';
  -- v2.15.265: scholarship site maps and searches only for providers that qualify (Australian with enough courses; overseas as before)
  elsif v_od is not null then
    -- on demand: the person saw the estimate and chose to run it; the daily shares and per-university caps do not apply, the allowance does
    perform pg_advisory_xact_lock(hashtext('fc_spend:on_demand'));
    if security.fc_on_demand_today_v1() + p_units > security.fc_setting_num_v1('ondemand_credits_per_day', 2000) then v_why := 'on_demand_allowance'; end if;
  elsif p_provider_id is not null and p_purpose in ('sch_map', 'sch_search') and not security.fc_sch_eligible_v1(p_provider_id) then
    v_why := 'not_eligible';
  elsif coalesce((select (s.value #>> '{}')::boolean from pipeline.platform_toolset_settings s where s.toolset_key = 'firecrawl' and s.key = 'daily_budget_on'), false) then
    perform pg_advisory_xact_lock(hashtext('fc_spend:' || v_grp));
    if security.fc_budget_left_v1(p_purpose) < p_units then
      v_why := case when security.fc_billed_today_v1() >= security.fc_setting_num_v1('daily_budget_total', 15000) then 'day_total' else 'share' end;
    elsif p_provider_id is not null and v_grp = 'scholarships'
          and (select coalesce(sum(x.units), 0) from pipeline.coverage_vendor_usage x where x.provider_id = p_provider_id and x.purpose like 'sch\_%' and x.at > security.fc_sch_cap_since_v1(p_provider_id))
              + p_units > security.fc_setting_num_v1('scholarship_cap_per_uni', 150)
          -- 16 Oct 2026: a scholarship page asked to be read again is not held by the per-university cap
          and not (p_purpose = 'sch_scrape' and exists (select 1 from pipeline.scholarship_pages sp join scholarship.scholarships s on s.id = sp.scholarship_id
                                                         where s.provider_id = p_provider_id and sp.url = p_url and sp.requested_at is not null)) then
      v_why := 'university_cap';
    elsif p_provider_id is not null and v_grp = 'central'
          and exists (select 1 from pipeline.coverage_vendor_usage x where x.provider_id = p_provider_id and security.fc_purpose_group_v1(x.purpose) = 'central'
                         and x.at > now() - make_interval(days => security.fc_setting_num_v1('central_refresh_days', 30)::int) and x.at < now() - interval '6 hours')  -- fixed: spends within the same central-page run
          -- Decision 265 (18 Oct 2026): a source a person added and not yet read is not held by the refresh interval
          and not exists (select 1 from pipeline.provider_fact_sources fs where fs.provider_id = p_provider_id and fs.url = p_url
                             and fs.status in ('found', 'reading') and fs.read_at is null)  -- 21 Oct 2026: any page never read (fee reader)
          -- 29 Oct 2026 (AER programme): nor is a seeded entry-requirements page never read
          and not exists (select 1 from pipeline.entry_matrix_sources es where es.provider_id = p_provider_id and es.url = p_url
                             and es.status in ('found', 'reading') and es.read_at is null) then
      v_why := 'not_due';
    elsif p_provider_id is not null and v_grp = 'course_search' and security.search_stop_gate_v1(p_provider_id) = 'search_stopped' then  -- S1: the one stop gate
      v_why := 'search_stopped';
    end if;
  end if;
  if v_why is not null then
    insert into pipeline.firecrawl_budget_refusals(day, grp, reason, n, last_at) values ((now() at time zone 'Australia/Melbourne')::date, v_grp, v_why, 1, now())
    on conflict (day, grp, reason) do update set n = pipeline.firecrawl_budget_refusals.n + 1, last_at = now();
    -- v2.15.265: and per university
    if p_provider_id is not null then
      insert into pipeline.firecrawl_refusals_by_provider(day, provider_id, grp, reason, n, last_at) values ((now() at time zone 'Australia/Melbourne')::date, p_provider_id, v_grp, v_why, 1, now())
      on conflict (day, provider_id, grp, reason) do update set n = pipeline.firecrawl_refusals_by_provider.n + 1, last_at = now();
    end if;
    return false;
  end if;
  insert into pipeline.coverage_vendor_usage(acquisition_provider_id, units, purpose, provider_id, url, on_demand_run)
  select id, p_units, p_purpose, p_provider_id, left(p_url, 500), v_od from pipeline.layer2_acquisition_providers where provider_key = 'firecrawl';
  return true;
end $function$
